// Generated by `just generate` from `src/plugins/claudetto/slices/minispec/adapters/validate.ts`. Edit the source and run `just generate`.
// The checks of `minispec validate`: a change, a spec, and the whole project (spec `minispec`, "Verification is a command, not prose").

import path from "node:path";
import {
  mergeDelta,
  parseDelta,
  parseRequirements,
  requirementIssues,
} from "../domain/spec.ts";
import { taskIssues } from "../domain/tasks.ts";
import { type Context, EXIT, type Issue, type Reply } from "../domain/types.ts";
import {
  ISSUE_DELTA_EMPTY,
  ISSUE_DESIGN_MISSING,
  ISSUE_PROPOSAL_MISSING,
  ISSUE_SPEC_EMPTY,
  ISSUE_SPEC_MISSING,
  ISSUE_TASKS_MISSING,
  VALIDATE_PROBLEMS_MANY,
  VALIDATE_PROBLEMS_ONE,
  VALIDATE_UNKNOWN,
} from "../prompts.ts";
import {
  changeNames,
  type Loaded,
  loadChange,
  readSpec,
  specNames,
} from "./load.ts";

/** The issues of a change that was read. */
export const changeIssues = async (
  ctx: Context,
  change: Loaded,
): Promise<Issue[]> => {
  const issue = (file: string, message: string): Issue => ({
    file: path.posix.join(change.dir, file),
    message,
  });
  const out: Issue[] = [];
  if (!change.proposal?.trim())
    out.push(issue("proposal.md", ISSUE_PROPOSAL_MISSING));
  if (change.tasks === null) out.push(issue("tasks.md", ISSUE_TASKS_MISSING));
  else for (const m of taskIssues(change.tasks)) out.push(issue("tasks.md", m));
  const bigHas = change.design !== null || change.specs.length > 0;
  if (bigHas && !change.design?.trim())
    out.push(issue("design.md", ISSUE_DESIGN_MISSING));
  if (bigHas && change.specs.length === 0)
    out.push(issue("specs", ISSUE_SPEC_MISSING));
  for (const { capability, text } of change.specs) {
    const file = `specs/${capability}/spec.md`;
    const delta = parseDelta(text);
    if (delta.added.length + delta.modified.length + delta.removed.length === 0)
      out.push(issue(file, ISSUE_DELTA_EMPTY));
    for (const m of requirementIssues([...delta.added, ...delta.modified]))
      out.push(issue(file, m));
    const merged = mergeDelta(
      capability,
      await readSpec(ctx, capability),
      delta,
    );
    if (!merged.ok) for (const m of merged.errors) out.push(issue(file, m));
  }
  return out;
};

/** The issues of the spec `capability`. */
export const specIssues = async (
  ctx: Context,
  capability: string,
): Promise<Issue[]> => {
  const file = `minispec/specs/${capability}/spec.md`;
  const reqs = parseRequirements((await readSpec(ctx, capability)) ?? "");
  if (reqs.length === 0)
    return [
      {
        file,
        message: ISSUE_SPEC_EMPTY,
      },
    ];
  return requirementIssues(reqs).map((message) => ({ file, message }));
};

/** The report of `issues`: JSON for a program, or one line for each issue for a person. */
const report = (checked: string[], issues: Issue[], json: boolean): Reply => {
  const code = issues.length === 0 ? EXIT.ok : EXIT.failed;
  if (json)
    return {
      code,
      out: JSON.stringify(
        { valid: issues.length === 0, checked, issues },
        null,
        2,
      ),
      err: "",
    };
  if (issues.length === 0)
    return {
      code,
      out: `Valid: ${checked.join(", ") || "nothing to check"}.`,
      err: "",
    };
  return {
    code,
    out: "",
    err: [
      ...issues.map((i) => `${i.file}: ${i.message}`),
      issues.length === 1
        ? VALIDATE_PROBLEMS_ONE
        : VALIDATE_PROBLEMS_MANY({ count: String(issues.length) }),
    ].join("\n"),
  };
};

/** `minispec validate [name]`. */
export const validateCommand = async (
  ctx: Context,
  name: string | undefined,
  json: boolean,
): Promise<Reply> => {
  const issues: Issue[] = [];
  const checked: string[] = [];
  const specs = await specNames(ctx);
  const changes = await changeNames(ctx);
  if (name !== undefined && !changes.includes(name) && !specs.includes(name))
    return {
      code: EXIT.failed,
      out: "",
      err: VALIDATE_UNKNOWN({ name }),
    };
  for (const n of changes)
    if (name === undefined || n === name) {
      const change = await loadChange(ctx, n);
      if (change) issues.push(...(await changeIssues(ctx, change)));
      checked.push(n);
    }
  for (const n of specs)
    if (name === undefined || (n === name && !changes.includes(name))) {
      issues.push(...(await specIssues(ctx, n)));
      checked.push(n);
    }
  return report(checked, issues, json);
};
